-- ============================================================================
-- WARDOGS SEASON 2 COMBAT APPLY 4a (ledger part a of a/b/c/d): game_data_changes history rows
-- STAGED, NOT RUN. Brief 318. Justin runs this in the Supabase SQL editor after review.
-- ============================================================================
-- Records part of the history of apply-1, apply-2 and apply-3 in game_data_changes: one row per changed field of an
-- updated row (old_value and new_value as jsonb, a value set to NULL is JSON null) and one insert row per inserted row
-- (new_value = the row data, old_value NULL). patch_id is looked up by game_slug wardogs + patch_key season-2.
-- This part owns the history rows of: wardogs_ballistics for Bushmaster M17S, A-91, KH-2002, T-21, Galil, M4, AK74, FAL, M249 SAW.
-- Run AFTER apply-1, apply-2 and apply-3: it checks they are in place and aborts if not, and aborts if this part already ran.
-- The ledger is split into parts only to keep each file under 250 KB. The parts do not depend on each other.
--
-- EXPECTED COUNTS (each statement asserts its count and RAISES EXCEPTION on any mismatch, which aborts
-- the whole transaction, so nothing is half-applied):
--   statement 1 INSERT game_data_changes: 868 rows
--     wardogs_ballistics update damage: 210
--     wardogs_ballistics update verified_source: 210
--     wardogs_ballistics update shots_to_kill: 137
--     wardogs_ballistics update shots_to_kill_raw: 137
--     wardogs_ballistics update armor_break_shots: 174
--
-- ATTRIBUTION written by the apply files (source_kind creator, confidence_tier attributed, verified false):
--   wardogs_ballistics verified_source:
--     Evo4Fun in-game testing workbook (EVA WARDOGS), sheet dated 30/10/2026, used with the author's permission (reported by operator), Season 2 per operator, attributed, not owner-verified
--   wardogs_ttk verified_source (updated rows), the new-weapon rows append the fire-rate clause:
--     Evo4Fun workbook shots-to-kill (sheet dated 30/10/2026, Season 2 per operator) [semicolon]  ttk_ms computed by Cybernetic Punks as (chest shots to kill - 1) x 60000 / fire rate, attributed, not owner-verified
--     ... + ", fire rate from the workbook Weapon Base Stats tab (nominal)"
--   weapon_stats verified_source: not changed (it holds the price provenance).
--   game_data_changes.note on every history row: Evo4Fun workbook, sheet dated 30/10/2026, Season 2 per operator, not matched to a patch by the sheet itself
--
-- INPUTS (sha256, all verified against their manifests before generation):
--   d7bff28b32d541ba113cf286dc97c54dcf45f30d1290017750861df1c1235957  proposals/2026-11-07-evo4fun-main-tabs/MANIFEST.txt
--   316be04993a1af1381a255f84e54c257f0e9c3dd11e9effdb5b36a47ea5060c9  proposals/2026-11-07-ttk-preview/MANIFEST.txt
--   b04d2761cfa0d797f7c1e6576bd5de3d391fabb0b0509b391ac2be37b259871d  2026-11-07-wardogs-baseline/MANIFEST.json
--   8e9d0314b981bebbea2695b2f710e96638d61822f80bc45014b06dfe2bdbf871  sources/swoleguy-2026-10-30/MANIFEST.txt
--   e2b319d63f8b3aab639eb5fde1a7c4ed4bc4ecf20436c7b2de76813ccecfc631  proposed_ballistics.csv
--   81a29dd330789ae1acd095d27e447678c49e354c9848345bd5815a0147c11081  classification.csv
--   3acdaccf83d16a6e769e0b760365861bba94ad192f6e5fa9076f9b5467fdaa93  proposed_ttk.csv
--
-- RUN ORDER (apply): apply-1-ballistics.sql, apply-2-ttk.sql, apply-3-fire-rate.sql, apply-4a-ledger-ballistics.sql, apply-4b-ledger-ballistics.sql, apply-4c-ledger-ballistics.sql, apply-4d-ledger-ttk-fire-rate.sql
-- RUN ORDER (full rollback): rollback-4d-ledger-ttk-fire-rate.sql, rollback-4c-ledger-ballistics.sql, rollback-4b-ledger-ballistics.sql, rollback-4a-ledger-ballistics.sql, rollback-3-fire-rate.sql, rollback-2-ttk.sql, rollback-1-ballistics.sql
-- RE-RUN: every UPDATE matches on the OLD (baseline 2026-11-07) values and every INSERT is pre-checked, so a
-- second run matches nothing and aborts on its count assertion or precheck. Nothing is applied twice.
-- ROLLBACK FILE: 2026-11-07-wardogs-s2-rollback-4a-ledger-ballistics.sql
-- ============================================================================
BEGIN;

DO $$
DECLARE n integer;
  pid bigint;
BEGIN
  SELECT count(*) INTO n FROM game_patches WHERE game_slug = 'wardogs' AND patch_key = 'season-2';
  IF n <> 1 THEN RAISE EXCEPTION 'game_patches: expected exactly 1 wardogs season-2 row, got %', n; END IF;
  SELECT id INTO pid FROM game_patches WHERE game_slug = 'wardogs' AND patch_key = 'season-2';
  SELECT count(*) INTO n FROM wardogs_ballistics WHERE game_slug = 'wardogs' AND verified_source = 'Evo4Fun in-game testing workbook (EVA WARDOGS), sheet dated 30/10/2026, used with the author''s permission (reported by operator), Season 2 per operator, attributed, not owner-verified';
  IF n <> 706 THEN RAISE EXCEPTION 'apply-1 not in place: expected 706 wardogs_ballistics rows with the Evo4Fun attribution, got %', n; END IF;
  SELECT count(*) INTO n FROM wardogs_ttk WHERE game_slug = 'wardogs' AND verified_source IN ('Evo4Fun workbook shots-to-kill (sheet dated 30/10/2026, Season 2 per operator); ttk_ms computed by Cybernetic Punks as (chest shots to kill - 1) x 60000 / fire rate, attributed, not owner-verified', 'Evo4Fun workbook shots-to-kill (sheet dated 30/10/2026, Season 2 per operator); ttk_ms computed by Cybernetic Punks as (chest shots to kill - 1) x 60000 / fire rate, attributed, not owner-verified, fire rate from the workbook Weapon Base Stats tab (nominal)');
  IF n <> 281 THEN RAISE EXCEPTION 'apply-2 not in place: expected 281 wardogs_ttk rows with the Evo4Fun attribution, got %', n; END IF;
  SELECT count(*) INTO n FROM weapon_stats WHERE game_slug = 'wardogs' AND (name, fire_rate) IN (('TCX-SPR', 800), ('PP-19 Bizon', 700), ('M14', 700), ('Evo-3 Ultra', 700));
  IF n <> 4 THEN RAISE EXCEPTION 'apply-3 not in place: expected 4 weapon_stats fire_rate rows, got %', n; END IF;
  IF EXISTS (SELECT 1 FROM game_data_changes c WHERE c.game_slug = 'wardogs' AND c.patch_id = pid AND c.note = 'Evo4Fun workbook, sheet dated 30/10/2026, Season 2 per operator, not matched to a patch by the sheet itself'
      AND ((c.table_name = 'wardogs_ballistics' AND c.row_key->>'weapon_name' IN ('Bushmaster M17S', 'A-91', 'KH-2002', 'T-21', 'Galil', 'M4', 'AK74', 'FAL', 'M249 SAW')))) THEN
    RAISE EXCEPTION 'game_data_changes part 4a: rows for this part already exist, nothing inserted';
