  INSERT INTO game_data_changes (game_slug, patch_id, table_name, row_key, field, change_type, old_value, new_value, note)
  SELECT 'wardogs', pid, v.table_name, v.row_key, v.field, v.change_type, v.old_value, v.new_value, 'Evo4Fun workbook, sheet dated 30/10/2026, Season 2 per operator, not matched to a patch by the sheet itself'
